// --- Overlong encodings and surrogate halves ---
//
// These are the canonical worked examples from the WHATWG spec: rejection
// happens on the FIRST continuation byte (narrowed boundary check), so the
// leading byte becomes one U+FFFD, and every remaining byte of the failed
// attempt - being a lone continuation byte with nothing to attach to -
// becomes its own additional U+FFFD.
static constexpr UTF32 Expected_Overlong_2Byte_Slash[] = {
    UTF32_REPLACEMENT_CHARACTER, UTF32_REPLACEMENT_CHARACTER};
static constexpr UTF32 Expected_Overlong_3Byte[] = {
    UTF32_REPLACEMENT_CHARACTER, UTF32_REPLACEMENT_CHARACTER,
    UTF32_REPLACEMENT_CHARACTER};
static constexpr UTF32 Expected_Surrogate_3Byte[] = {
    UTF32_REPLACEMENT_CHARACTER, UTF32_REPLACEMENT_CHARACTER,
    UTF32_REPLACEMENT_CHARACTER};
static constexpr UTF32 Expected_Overlong_Or_OutOfRange_4Byte[] = {
    UTF32_REPLACEMENT_CHARACTER, UTF32_REPLACEMENT_CHARACTER,
    UTF32_REPLACEMENT_CHARACTER, UTF32_REPLACEMENT_CHARACTER};

INSTANTIATE_TEST_SUITE_P(
    OverlongAndSurrogate, Convert_UTF8_to_UTF32_LOSSLY_Test,
    ::testing::Values(
        Convert_UTF8_to_UTF32_Case{
            "\xC0\xAF", Expected_Overlong_2Byte_Slash,
            "Overlong encoding of '/' (classic 2-U+FFFD example)"},
        Convert_UTF8_to_UTF32_Case{
            "\xE0\x9F\x80", Expected_Overlong_3Byte,
            "Overlong 3-byte: 0xE0's continuation must be >= 0xA0"},
        Convert_UTF8_to_UTF32_Case{"\xE0\x80\x80", Expected_Overlong_3Byte,
                                   "Overlong 3-byte encoding of U+0000"},
        Convert_UTF8_to_UTF32_Case{
            "\xED\xA0\x80", Expected_Surrogate_3Byte,
            "Surrogate U+D800: 0xED's continuation must be <= 0x9F"},
        Convert_UTF8_to_UTF32_Case{
            "\xED\xBF\xBF", Expected_Surrogate_3Byte,
            "Surrogate U+DFFF: 0xED's continuation must be <= 0x9F"},
        Convert_UTF8_to_UTF32_Case{
            "\xF0\x80\x80\x80", Expected_Overlong_Or_OutOfRange_4Byte,
            "Overlong 4-byte: 0xF0's continuation must be >= 0x90"},
        Convert_UTF8_to_UTF32_Case{
            "\xF4\x90\x80\x80", Expected_Overlong_Or_OutOfRange_4Byte,
            "Beyond U+10FFFF: 0xF4's continuation must be <= 0x8F"}));

