INSTANTIATE_TEST_SUITE_P(
    ZeroSizeInput, Convert_UTF8_to_UTF32_LOSSLY_Test,
    ::testing::Values(Convert_UTF8_to_UTF32_Case{
        "", {}, "Empty input: returns 0, output buffer contents undefined"}));

