//------------------------------------------------------------------------------
//
// Destination buffer capacity handling
//
//------------------------------------------------------------------------------

TEST(Convert_UTF8_to_UTF32_LOSSLY_CapacityTest, ExactCapacitySucceeds) {
  static constexpr std::string_view Input = "\xE2\x82\xAC"; // Euro, 1 CP
  std::array<UTF32, 1> Buffer{};

  ptrdiff_t N =
      convert_UTF8_to_UTF32_LOSSLY(Input, Buffer.data(), Buffer.size());

  ASSERT_EQ(N, 1);
  EXPECT_EQ(Buffer[0], static_cast<UTF32>(0x20AC));
}

TEST(Convert_UTF8_to_UTF32_LOSSLY_CapacityTest,
     InsufficientCapacityReturnsNegative) {
  static constexpr std::string_view Input = "\xE2\x82\xAC\xE2\x99\xA5"; // 2 CPs
  std::array<UTF32, 1> Buffer{}; // Only room for 1, but input has 2.

  ptrdiff_t N =
      convert_UTF8_to_UTF32_LOSSLY(Input, Buffer.data(), Buffer.size());

  EXPECT_LT(N, 0) << "Destination buffer is too small to hold every "
                     "decoded codepoint";
}
